def simuler(P, graine):
    """Tire P personnes au hasard : le sexe (homme = 1, deux tiers d'hommes), puis la taille, en cm."""
    rng = np.random.default_rng(graine)
    homme = (rng.random(P) < 2 / 3).astype(int)
    taille = np.where(homme == 1, rng.normal(176, 6.7, P), rng.normal(163, 6.7, P))
    return pd.DataFrame({"taille": taille.round(1), "homme": homme})


donnees = simuler(3000, graine=0)
print(donnees["homme"].value_counts())
sns.histplot(data=donnees, x="taille", hue="homme", binwidth=1);

for nom, y_p in [("taille > 170", y_predit), ("naïf", y_naif)]:
